WITH v AS (SELECT v.id FROM cartillas.versiones v JOIN cartillas.plantillas p ON p.id=v.plantilla_id WHERE p.codigo='BOGIE' AND v.numero=1), datos(titulo,orden) AS (VALUES
 ('Conjunto bogie',1),('Suspensión secundaria',2),('Acoplamiento elástico',3),('Caja de grasa/ Rodamientos',4),('Reductora',5),('Biela de reacción',6),('OBSERVACIONES',7),('RELACIÓN DE ANOMALÍAS CORREGIDAS DURANTE LA REVISIÓN',8),('RELACIÓN DE OPERACIONES PENDIENTES',9),('PERSONAL',10))
INSERT INTO cartillas.secciones (version_id,titulo,orden) SELECT v.id,datos.titulo,datos.orden FROM v CROSS JOIN datos
ON CONFLICT (version_id,orden) DO UPDATE SET titulo=EXCLUDED.titulo,activo=TRUE,actualizado_en=CURRENT_TIMESTAMP;

